(()=>{'use strict';const A=RepoAccount,U=RepoAdminUI,$=s=>document.querySelector(s),esc=U.esc;window.RepoLaunchAnalytics=(data,rows=[])=>{if(!data?.configured)return '<section class="analytics-box"><h3>Discovery conversions</h3><p>Apply migration 10 to activate conversion tracking. Existing visitor counts remain available.</p></section>';const rate=(n,d)=>d?Math.round(n/d*1000)/10+'%':'—',metric=(n,d,label)=>`<div class="metric"><strong>${rate(n,d)}</strong><span>${esc(label)}</span><small>${Number(n||0)} of ${Number(d||0)} listing sessions</small></div>`,names=new Map(rows.map(r=>[r.builtin_key||r.id,r.title]));return `<section class="analytics-box"><h3>From discovery to making it your own</h3><div class="conversion-grid">${metric(data.viewToDemo,data.listingSessions,'Listing → demo')}${metric(data.viewToLike,data.listingSessions,'Listing → like')}${metric(data.demoToLike,data.demoSessions,'Demo → like')}${metric(data.signInCompletions,data.signInStarts,'Sign-in completion')}<div class="metric"><strong>${Number(data.verifiedForks||0)}</strong><span>Newly verified forks</span><small>${Number(data.forkClicks||0)} fork / duplicate clicks</small></div><div class="metric"><strong>${Number(data.returningVisitors||0)}</strong><span>Returning browsers</span></div></div><p class="analytics-caption">Tracking began ${esc(new Date(data.startedAt).toLocaleDateString())}. Conversions count sessions with the same listing and an observed sequence. Demo clicks do not prove demo usage or cause a like. Returning browsers appeared on more than one UTC day in this range. Verified forks are newly observed during a fork check, not proof of a fork created through RepoShelf.</p><h4>Storefront row activity</h4><div class="help-table-wrap"><table class="analytics-table"><thead><tr><th>Row</th><th>Listing views</th><th>Demos</th><th>Likes</th><th>Fork clicks</th></tr></thead><tbody>${(data.rows||[]).map(r=>`<tr><td>${esc(names.get(r.shelf)||({all:'All projects',direct:'Direct listing',hero:'In the spotlight'})[r.shelf]||r.shelf)}</td><td>${Number(r.listing_views)}</td><td>${Number(r.demo_clicks)}</td><td>${Number(r.likes)}</td><td>${Number(r.fork_clicks)}</td></tr>`).join('')||'<tr><td colspan="5">Activity will appear after eligible visits.</td></tr>'}</tbody></table></div></section>`};
let epoch=0,qualityEpoch=0,reportsEpoch=0,quality=[],reports=[],editing=null,offset=0,reportOffset=0,timer;
const issueNames={category_review:'Subject classification needs review',provider_preview:'Provider image awaiting approval',pending:'Pending admission',quarantined:'Quarantined after repeated failures',browser_unattempted:'Browser work never attempted',browser_repeated:'Repeated browser failures',repository_check:'Repository check due',demo_check:'Demo check due',broken_demo:'Demo needs attention',retry:'Awaiting retry',screenshot:'Missing screenshot',description:'Short description',licence:'Licence missing',category:'Category missing',unavailable:'Unavailable',hidden:'Hidden or excluded',excluded:'Permanently excluded'};
const migration10='<p>Apply <a href="https://github.com/sparx1981/RepoShelf/blob/main/supabase/migrations/202610040010_launch_quality_moderation_analytics.sql" target="_blank" rel="noopener">migration 10</a>, then refresh this tab.</p>';
function error(slot,e,retry){if(e.status===401||e.status===403)void A.refresh();U.show(slot,U.errorHtml(e.message,retry)+(e.code==='migration_required'?migration10:''))}
const metric=(n,label,suffix='',tip)=>`<div class="metric"><strong>${Number(n||0).toLocaleString()}${suffix}</strong><span>${esc(label)}${tip?U.info(label,tip):''}</span></div>`;
const SEVEN='Successful demo checks and screenshots are revisited after seven days.';
const TIPS={
 repository:{what:'The share of available listings whose GitHub repository was checked in the last 48 hours: still public, not renamed or removed, with current description, licence and stars.',why:'Repositories get deleted or archived. A listing is only published while this check is fresh.',often:'Each repository every 48 hours. The sync runs every two hours and works through those due, within GitHub’s request allowance.',note:'Target 95%.'},
 demo:{what:'The share of available listings whose demo opened in an isolated browser within the last seven days and gave a clear result: working, needs review or unavailable.',why:'The demo is the point of a listing, and this stops visitors landing on dead links. Passing means the page loaded, not that every feature works.',often:'Working demos every seven days. After three failures in a row the wait is 24 hours; blocked or unresolved addresses wait seven days.',note:'Target 95%.'},
 screenshots:{what:'The share of listings with a demo that have a screenshot of the current demo address. Listings whose demo is unavailable are left out.',why:'Cards and detail pages lead with the screenshot, and a listing cannot be published without one.',often:'Taken during the same browser visit as demo validation, then every seven days or when the repository changes. A failed capture never replaces a good one.',note:'Target 90%.'},
 featured:{what:'Of the listings you picked for Featured and Hero rows, the share that currently qualify: published, with a working demo checked within seven days and a real screenshot.',why:'The storefront hides picks that do not qualify, so anything under 100% is a gap in the first row visitors see. “Ready to feature” counts every qualifying listing, not just your picks.',often:'Recalculated whenever this tab loads. A pick drops out when its checks age and returns after the next successful one.',note:'Target 100%.'}
};
const TILE_TIPS={
 published:{what:'Listings that pass every admission check right now: repository checked within 48 hours, demo working within seven days, and a screenshot of the current demo.',why:'Only these appear on the public storefront and in the agent API.',often:'Re-evaluated every sync (every two hours). The public site updates at the daily publication, 06:35 UTC, or on Publish now.'},
 pending:{what:'Saved listings with missing or expired evidence: no fresh repository check, no working demo, or no screenshot yet.',why:'Discovery keeps saving candidates. They wait here so visitors only see verified listings.',often:'Retried every sync, starting with those never tried.'},
 failing:{what:'Visible listings where the demo check or screenshot capture failed three or more times in a row. They are normally quarantined, which keeps them out of public browsing.',why:'An automated browser cannot always tell a broken demo from one that blocks robots or needs a login. Repeated failure is when a person should look.',often:'Retries continue: after three failures the wait is 24 hours, lengthening to three days after six. Nothing is deleted automatically.'},
 working:{what:'Listings whose demo opened successfully within the last seven days with no error.',why:'Shows how much of the saved catalogue has a demo known to work.',often:SEVEN},
 ready:{what:'Every listing that would qualify to be featured: published, working demo checked within seven days, real screenshot.',why:'This is the pool Featured and Hero rows can draw from. Featured selection eligibility only counts the listings you have picked.',often:'Recalculated whenever this tab loads.'},
 broken:{what:'Listings whose latest clear demo check says the demo is unavailable or needs review.',why:'These demos are the most likely to disappoint visitors.',often:'Rechecked after seven days, or sooner when a visitor reports the listing.'},
 shots:{what:'Listings with a demo but no screenshot of the current demo address.',why:'A listing cannot be published without a screenshot.',often:'Captured on the next browser visit, then refreshed every seven days.'}
};
const REASON_GROUPS=[
 {id:'dead',label:'Link may be dead',meaning:'The domain or server could not be reached.',action:'Check the demo URL upstream, or exclude the listing.',test:r=>/^(dns_|connection_refused|http_5(2[0-9]|30))/.test(r)},
 {id:'blocked',label:'Blocked or needs sign-in',meaning:'The demo may work for people but stops automated checks.',action:'Open the demo yourself. If it works, no action is needed.',test:r=>/^(access_restricted|login_wall|rate_limit|http_40[123]|http_451)/.test(r)},
 {id:'blank',label:'Loaded blank or identical',meaning:'The page rendered nothing useful for a screenshot.',action:'Look at the demo; it may need interaction or more load time.',test:r=>/^(empty_page|uniform_image)/.test(r)},
 {id:'slow',label:'Timed out',meaning:'The demo was too slow or the network failed. Often temporary.',action:'Usually none. It retries automatically.',test:r=>/^(network_or_timeout|probe_timeout)/.test(r)},
 {id:'server',label:'Server returned an error',meaning:'The demo’s server answered with an error status.',action:'Usually none unless it persists for days.',test:r=>/^(http_[45]|application_error)/.test(r)},
 {id:'unsafe',label:'Not a public web address',meaning:'The link points somewhere private or unsupported, so it is never opened.',action:'Correct it upstream or exclude the listing.',test:r=>r==='unsafe_target'},
 {id:'capture',label:'Screenshot capture failed',meaning:'The demo loaded but the image could not be saved.',action:'Retries automatically.',test:r=>r==='screenshot_error'}
];
function reasonTable(reasons={}){const rows=REASON_GROUPS.map(g=>({...g,count:0,keys:[]}));let other=0;for(const [reason,count] of Object.entries(reasons)){const g=rows.find(x=>x.test(reason));if(g){g.count+=count;g.keys.push(reason.replaceAll('_',' ')+' ('+count+')')}else other+=count}const shown=rows.filter(g=>g.count).sort((a,b)=>b.count-a.count);if(other)shown.push({label:'Other',meaning:'Reasons that do not fit the groups above.',action:'Open the listing for the saved reason.',count:other,keys:[]});return shown.length?`<div class="help-table-wrap"><table class="analytics-table reason-table"><thead><tr><th>Most likely cause</th><th class="num">Listings</th><th>What it usually means</th><th>What to do</th></tr></thead><tbody>${shown.map(g=>`<tr><th scope="row">${esc(g.label)}${g.keys.length?`<small>${esc(g.keys.join(', '))}</small>`:''}</th><td class="num">${Number(g.count).toLocaleString()}</td><td>${esc(g.meaning)}</td><td>${esc(g.action)}</td></tr>`).join('')}</tbody></table></div>`:'<p class="analytics-caption">No listings are failing repeatedly.</p>'}
function targetRow(t){const detail=t.id==='featured'?(t.of?`${Number(t.count).toLocaleString()} of ${Number(t.of).toLocaleString()} picks${t.notInCatalogue>0?` · ${Number(t.notInCatalogue).toLocaleString()} not in the catalogue`:''}`:'No featured picks saved yet'):`${Number(t.count).toLocaleString()} of ${Number(t.of).toLocaleString()} listings`;return `<tr role="row"><th scope="row" role="rowheader">${esc(t.label)}${U.info(t.label,TIPS[t.id]||{what:t.label})}</th><td class="num" role="cell"><strong>${Number(t.actual)}%</strong><small>${esc(detail)}<span class="target-inline"> · target ${Number(t.target)}%</span></small></td><td class="num target-col" role="cell">${Number(t.target)}%</td><td role="cell">${t.met?U.pill('met','Met','ok'):U.pill('attention','Needs attention','warn')}</td></tr>`}
async function loadQuality(append=false){const token=++qualityEpoch;if(!append)offset=0;const slot=$('#quality-content');if(!U.loaded(slot))U.show(slot,'<p class="loading-note"><span class="rs-loader rs-loader-sm" aria-hidden="true"></span>Loading catalogue quality…</p>');slot.setAttribute('aria-busy','true');try{const data=await A.request('/api/editorial?action=quality&offset='+offset+'&issue='+encodeURIComponent($('#quality-issue').value)+'&q='+encodeURIComponent($('#quality-search').value));if(token!==qualityEpoch||!A.user?.admin)return;quality=append?[...quality,...data.items]:data.items;offset=data.nextOffset;const c=data.coverage,targets=data.targets||[],unmet=targets.filter(t=>!t.met).length,bb=c.browserBacklog;U.flag('quality',unmet?'warn':null,unmet+' launch target'+(unmet===1?'':'s')+' not met');
U.patch(slot,`<p class="analytics-caption">Quality source: ${esc(data.qualitySource||'Deployed catalogue')}${data.qualityAsOf?' · Saved '+esc(new Date(data.qualityAsOf).toLocaleString()):''}.</p>${data.milestone?`<section class="analytics-box"><h3>First milestone: 5,000 published listings</h3><div class="metric-grid">${metric(data.milestone.published,'Quality-ready listings')}${metric(data.milestone.remaining,'To the first milestone')}${metric(data.milestone.percent,'Progress','%')}</div><progress aria-label="Progress towards 5,000 published listings" value="${Number(data.milestone.published)}" max="5000"></progress><p class="analytics-caption">5,000 is the first milestone. Discovery continues beyond it; there is no catalogue ceiling. Pending repairs do not count towards this goal.</p></section>`:''}${targets.length?`<section class="analytics-box"><div class="panel-heading"><h3>Launch quality targets</h3>${U.pill(unmet?'attention':'met',unmet?unmet+' of '+targets.length+' not met':'All targets met',unmet?'warn':'ok')}</div><div class="help-table-wrap"><table class="analytics-table targets-table" role="table"><thead role="rowgroup"><tr role="row"><th role="columnheader">Check</th><th class="num" role="columnheader">Coverage</th><th class="num target-col" role="columnheader">Target</th><th role="columnheader">Status</th></tr></thead><tbody role="rowgroup">${targets.map(targetRow).join('')}</tbody></table></div><p class="analytics-caption">Coverage is measured across every saved listing that is still available, including those waiting for admission; it does not block discovery, and only listings that pass every check are published. Working-demo counts are separate. Review every featured screenshot and description by hand before launch: passing automated checks does not confirm every demo feature works.</p></section>`:''}<div class="metric-grid">${metric(c.total,'Saved projects')}${metric(c.publication?.published,'Published quality-ready projects','',TILE_TIPS.published)}${metric(c.publication?.pending,'Pending admission','',TILE_TIPS.pending)}${metric(bb?.reviewCount,'Failing repeatedly','',TILE_TIPS.failing)}${metric(c.workingDemos,'Confirmed working demos','',TILE_TIPS.working)}${metric(c.featuredEligible,'Ready to feature','',TILE_TIPS.ready)}${metric(c.broken_demo,'Demos needing attention','',TILE_TIPS.broken)}${metric(c.screenshot,'Missing screenshots','',TILE_TIPS.shots)}</div>${bb?.reviewCount?`<details class="analytics-box"><summary>Why ${Number(bb.reviewCount).toLocaleString()} listings keep failing</summary>${reasonTable(bb.reviewReasons)}<p class="analytics-caption">Failing repeatedly means at least three consecutive failed demo checks or screenshot captures. These listings stay saved and keep retrying; nothing is deleted. Filter the listing search by “Repeated browser failures” to open them.</p></details>`:''}<details class="analytics-box"><summary>Browser backlog, retries and coverage</summary><div class="metric-grid">${metric(c.demo_check,'Demo checks due')}${metric(c.retry,'Awaiting retries')}${metric(bb?.demo.never,'Demo validation never attempted')}${metric(bb?.screenshot.never,'Screenshot never attempted')}${metric(bb?.demo.repeated,'Repeated demo failures')}${metric(bb?.screenshot.repeated,'Repeated screenshot failures')}${metric(c.repositoryCoverage,'Repository check coverage','%')}${metric(c.demoCoverage,'Demo validation coverage','%')}${metric(c.screenshotCoverage,'Demo screenshot coverage','%')}</div><p class="analytics-caption">Counts include the saved processing catalogue. Only fresh checked repositories with working demos and captured screenshots enter public browsing. Pending and quarantined records stay saved for repair, and screenshots become public at catalogue publication. Run capture totals can include refreshes; coverage counts distinct listings. Repeated failures mean at least three consecutive attempts. Featured listings need a successful demo check in the last seven days and a usable preview. Queue order: featured selections, frequently viewed listings, then completeness. Refresh requests are picked up by the next scheduled maintenance run.</p></details><h3 class="list-heading">Listings</h3><div class="quality-list">${quality.map(r=>`<article class="quality-item"><div><strong>${esc(r.name)}</strong><small>${esc(r.id)} · ${esc(r.control.visibility)} · ${esc(r.catalogueState||'pending')}${r.featured?' · Featured selection':''}${r.featuredEligible?' · Ready to feature':''}</small>${r.issues.length?`<ul class="chip-list">${r.issues.map(i=>`<li class="chip">${esc(issueNames[i]||i)}</li>`).join('')}</ul>`:'<p class="small">No quality issues detected</p>'}${r.browserBacklog?.reason?`<p class="small">Last browser issue: ${esc(r.browserBacklog.reason.replaceAll('_',' '))} · ${Number(r.browserBacklog.demoFailures)} consecutive demo failures · ${Number(r.browserBacklog.previewFailures)} consecutive capture failures${r.browserBacklog.nextRetryAt?' · Retry after '+esc(new Date(r.browserBacklog.nextRetryAt).toLocaleString()):''}</p>`:''}${r.browserBacklog?.reviewAdvice?`<p class="small">${esc(r.browserBacklog.reviewAdvice)}</p>`:''}</div>${r.previewCandidate?.reviewRequired?`<div><img class="moderation-preview" style="max-width:240px" src="${esc(r.previewCandidate.displaySrc||r.previewCandidate.src)}" alt="Screenshot candidate for ${esc(r.name)}"><p class="small">${esc(r.previewCandidate.provider)} · Review the actual demo before approving.</p>${r.control.approved_preview===r.previewCandidate.src?'<p class="small">Approved · awaiting next sync</p>':`<button class="button outline" data-approve-preview="${esc(r.id)}">Approve preview</button>`}</div>`:''}<button class="button outline" data-quality-edit="${esc(r.id)}">Review listing</button></article>`).join('')||'<p class="chart-empty">No matching listings.</p>'}</div>${offset!==null?'<button class="button outline" id="quality-more">Load more</button>':''}<details class="analytics-box"><summary>Coverage history</summary><div class="help-table-wrap"><table class="analytics-table"><thead><tr><th>Date</th><th>Records</th><th>Previews</th><th>Unavailable</th></tr></thead><tbody>${(data.history||[]).map(r=>`<tr><td>${esc(r.at?.slice(0,10))}</td><td>${Number(r.records||0)}</td><td>${Number(r.withScreenshot||0)}</td><td>${Number(r.unavailable||0)}</td></tr>`).join('')}</tbody></table></div><p class="analytics-caption">Historical previews can include author-provided images; current missing-screenshot counts require a captured demo image.</p></details>`);$('#quality-more')?.addEventListener('click',()=>loadQuality(true))}catch(e){if(token===qualityEpoch&&A.user?.admin)error(slot,e,'quality')}finally{if(token===qualityEpoch)slot.removeAttribute('aria-busy')}}
async function refreshQuality(){const wanted=quality.length;await loadQuality();while(offset!==null&&quality.length<wanted&&A.user?.admin){const before=quality.length;await loadQuality(true);if(quality.length===before)break}}
async function loadReports(append=false){const token=++reportsEpoch;if(!append)reportOffset=0;const slot=$('#reports-content');if(!U.loaded(slot))U.show(slot,'<p class="loading-note"><span class="rs-loader rs-loader-sm" aria-hidden="true"></span>Loading reports…</p>');slot.setAttribute('aria-busy','true');try{const data=await A.request('/api/editorial?action=reports&status='+$('#reports-status').value+'&offset='+reportOffset);if(token!==reportsEpoch||!A.user?.admin)return;reports=append?[...reports,...data.items]:data.items;reportOffset=data.nextOffset;if($('#reports-status').value==='open'){const n=reports.length;U.flag('reports',n?'warn':null,n+(reportOffset!==null?'+':'')+' open')}
U.show(slot,reports.map(r=>`<article class="quality-item report-item"><div><strong>${esc(r.project_id)}</strong><small>${esc(r.reason.replaceAll('_',' '))} · ${esc(new Date(r.created_at).toLocaleString())}</small><p>${esc(r.explanation)||'No additional explanation.'}</p><div class="report-actions">${U.pill(r.status==='open'?'attention':r.status==='reviewed'?'success':'unknown',r.status,r.status==='open'?'warn':r.status==='reviewed'?'ok':'neutral')}<button class="button outline" data-report-listing="${esc(r.project_id)}">Review listing</button>${r.status==='open'?`<label class="report-note"><span class="sr-only">Private note (optional)</span><input data-report-note="${esc(r.id)}" maxlength="2000" placeholder="Private note (optional)"></label><button class="button outline" data-review-report="${esc(r.id)}" data-status="reviewed">Mark reviewed</button><button class="button outline quiet" data-review-report="${esc(r.id)}" data-status="dismissed">Dismiss report</button>`:''}</div></div></article>`).join('')||'<p class="chart-empty">No reports in this view. Reports from signed-in users appear here.</p>');if(reportOffset!==null)slot.insertAdjacentHTML('beforeend','<button class="button outline" id="reports-more">Load more</button>');$('#reports-more')?.addEventListener('click',()=>loadReports(true))}catch(e){if(token===reportsEpoch&&A.user?.admin)error(slot,e,'reports')}finally{if(token===reportsEpoch)slot.removeAttribute('aria-busy')}}
function moderationState(){const leaving=$('#moderation-visibility').value==='excluded'&&editing?.control.visibility!=='excluded';$('#moderation-warning').hidden=!leaving;$('#moderation-save').textContent=leaving?'Exclude permanently':'Save changes'}
async function editListing(id){let row=quality.find(r=>r.id===id);if(!row){$('#quality-search').value=id;$('#quality-issue').value='';await loadQuality();row=quality.find(r=>r.id.toLowerCase()===id.toLowerCase())}if(!row||!A.user?.admin)return;editing=row;const c=row.control;$('#moderation-title').textContent=row.name;$('#moderation-id').textContent=row.id;const summary=document.getElementById('moderation-classification');summary.textContent='Subjects: '+(row.subjects?.join(', ')||'No confident subject match')+(row.classification?.suggestedSubjects?.length?' · Suggestions to review: '+row.classification.suggestedSubjects.join(', '):'')+'. Category overrides take precedence.';$('#moderation-description').value=c.description||'';$('#moderation-original').textContent=row.authorDescription;$('#moderation-category').value=c.category||'';$('#moderation-visibility').value=c.visibility;$('#moderation-reject').checked=c.preview_rejected;$('#moderation-refresh').checked=false;$('#moderation-note').value='';$('#moderation-message').textContent='';moderationState();const image=$('#moderation-preview');image.hidden=!row.preview;if(row.preview?.src)image.src=row.preview.src;else image.removeAttribute('src');$('#moderation-dialog').showModal();const token=qualityEpoch;try{const data=await A.request('/api/editorial?action=audit&id='+encodeURIComponent(id));if(token!==qualityEpoch||editing?.id!==id||!A.user?.admin)return;$('#moderation-audit').innerHTML=data.items.map(r=>`<p><strong>${esc(r.action.replaceAll('_',' '))}</strong> · ${esc(new Date(r.created_at).toLocaleString())}<br>${esc(r.note)}<small>Administrator account: ${esc(r.actor||'Removed account')}</small></p>`).join('')||'<p>No moderation changes yet.</p>'}catch(e){if(A.user?.admin)$('#moderation-audit').textContent=e.message}}
$('#moderation-form').onsubmit=async event=>{event.preventDefault();if(!editing)return;const row=editing,button=$('#moderation-save'),excluding=$('#moderation-visibility').value==='excluded'&&row.control.visibility!=='excluded',refresh=$('#moderation-refresh').checked;button.disabled=true;try{await A.request('/api/editorial?action=moderate',{method:'POST',body:JSON.stringify({id:row.id,revision:row.control.revision,visibility:$('#moderation-visibility').value,description:$('#moderation-description').value,category:$('#moderation-category').value,rejectPreview:$('#moderation-reject').checked,preview:row.preview?.src||row.control.rejected_preview||null,refresh,note:$('#moderation-note').value})});$('#moderation-dialog').close();U.toast(excluding?'Listing excluded from discovery.':refresh?'Listing updated. A fresh validation was requested.':'Listing updated.');void refreshQuality()}catch(e){$('#moderation-message').textContent=e.message;if(e.status===409){$('#moderation-dialog').close();U.toast('That listing changed while you were editing. Reloaded the latest version.','warning');await refreshQuality()}}finally{button.disabled=false}};
$('#moderation-dialog .close').onclick=()=>$('#moderation-dialog').close();$('#moderation-cancel').onclick=()=>$('#moderation-dialog').close();$('#moderation-visibility').onchange=moderationState;$('#refresh-quality').onclick=()=>loadQuality();$('#quality-issue').onchange=()=>loadQuality();$('#quality-search').oninput=()=>{clearTimeout(timer);timer=setTimeout(()=>loadQuality(),250)};$('#refresh-reports').onclick=()=>loadReports();$('#reports-status').onchange=()=>loadReports();
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(b?.dataset.adminTab==='quality')void loadQuality();if(b?.dataset.adminTab==='reports')void loadReports();if(b?.dataset.retry==='quality')void loadQuality();if(b?.dataset.retry==='reports')void loadReports();if(b?.dataset.approvePreview){const row=quality.find(r=>r.id===b.dataset.approvePreview);if(!row)return;b.disabled=true;try{await A.request('/api/editorial?action=approve-preview',{method:'POST',body:JSON.stringify({id:row.id,revision:row.control.revision,preview:row.previewCandidate.src})});U.toast('Preview approved. The next sync will apply it.');await loadQuality()}catch(err){U.toast(err.message,'error')}finally{b.disabled=false}}if(b?.dataset.qualityEdit)void editListing(b.dataset.qualityEdit);if(b?.dataset.reportListing)void editListing(b.dataset.reportListing);if(b?.dataset.reviewReport){const report=reports.find(r=>r.id===b.dataset.reviewReport),note=document.querySelector(`[data-report-note="${CSS.escape(b.dataset.reviewReport)}"]`)?.value||'';if(!report)return;b.disabled=true;try{await A.request('/api/editorial?action=review-report',{method:'POST',body:JSON.stringify({id:report.id,revision:report.revision,status:b.dataset.status,note})});U.toast(b.dataset.status==='reviewed'?'Report marked reviewed.':'Report dismissed.');await loadReports()}catch(err){b.disabled=false;U.toast(err.message,'error');if(err.status===409)await loadReports()}}});
window.addEventListener('reposhelf-account',()=>{if(!A.user?.admin){epoch++;qualityEpoch++;reportsEpoch++;quality=[];reports=[];editing=null;U.clear($('#quality-content'));U.clear($('#reports-content'));$('#moderation-audit').innerHTML='';$('#moderation-form').reset();$('#moderation-original').textContent='';$('#moderation-preview').removeAttribute('src');$('#moderation-dialog').close()}else{const tab=new URL(location.href).searchParams.get('tab');if(tab==='quality')void loadQuality();if(tab==='reports')void loadReports()}});
if(A.user?.admin){const tab=new URL(location.href).searchParams.get('tab');if(tab==='quality')void loadQuality();if(tab==='reports')void loadReports()}
})();
